# shellcheck shell=bash
# Base system configuration: identity, locale, fstab and accounts.

system_write_hostname() {
    local hosts="$GI_ROOT/etc/hosts"
    ensure_dir "$GI_ROOT/etc"
    printf '%s\n' "$CFG_HOSTNAME" | write_file_atomic "$GI_ROOT/etc/hostname" 0644
    write_file_atomic "$hosts" 0644 <<EOF
# Generated by ${GI_NAME}
127.0.0.1   localhost
::1         localhost
127.0.1.1   ${CFG_HOSTNAME}
EOF
    if [[ $CFG_INIT == openrc ]]; then
        ensure_dir "$GI_ROOT/etc/conf.d"
        printf 'hostname="%s"\n' "$CFG_HOSTNAME" |
            write_file_atomic "$GI_ROOT/etc/conf.d/hostname" 0644
    fi
    log_info "hostname set: $CFG_HOSTNAME"
}

system_write_timezone() {
    local zonefile="$GI_ROOT/usr/share/zoneinfo/$CFG_TIMEZONE"
    local hwopt=--utc
    [[ $CFG_HWCLOCK == local ]] && hwopt=--localtime
    if [[ $CFG_TIMEZONE != UTC && ! -e $zonefile ]]; then
        ui_error "Часовой пояс не найден" "В stage3 нет ${zonefile}."
        return 1
    fi
    ln -sfn "/usr/share/zoneinfo/${CFG_TIMEZONE}" "$GI_ROOT/etc/localtime"
    printf '%s\n' "$CFG_TIMEZONE" | write_file_atomic "$GI_ROOT/etc/timezone" 0644
    if [[ $CFG_INIT == openrc ]]; then
        ensure_dir "$GI_ROOT/etc/conf.d"
        {
            printf '# Generated by %s %s\n' "$GI_NAME" "$GI_VERSION"
            printf 'clock="%s"\n' "$CFG_HWCLOCK"
            printf 'clock_systohc="YES"\n'
        } | write_file_atomic "$GI_ROOT/etc/conf.d/hwclock" 0644
    fi
    # An unavailable RTC must not abort the whole installation. Record the
    # UTC/local choice in /etc/adjtime so the installed system still knows it.
    if ! chroot "$GI_ROOT" /bin/bash -lc "hwclock --systohc ${hwopt}" >>"$GI_LOG_FILE" 2>&1; then
        warn "не удалось записать время в RTC; установка продолжится"
        printf '0.0 0 0.0\n0\n%s\n' "$CFG_HWCLOCK" |
            write_file_atomic "$GI_ROOT/etc/adjtime" 0644
    fi
    log_info "timezone set: $CFG_TIMEZONE (hwclock=$CFG_HWCLOCK)"
}

system_write_locale() {
    local locale=$CFG_LOCALE
    ensure_dir "$GI_ROOT/etc/env.d"
    printf '%s UTF-8\n' "$locale" | write_file_atomic "$GI_ROOT/etc/locale.gen" 0644
    printf 'LANG="%s"\n' "$locale" | write_file_atomic "$GI_ROOT/etc/env.d/02locale" 0644
    printf 'LANG=%s\n' "$locale" | write_file_atomic "$GI_ROOT/etc/locale.conf" 0644
    chroot_run "Генерация локали ${locale}" locale-gen || return 1
    chroot_run "Обновление окружения" env-update || return 1
    log_info "locale set: $locale"
}

system_write_keymap() {
    local keymap=$CFG_KEYMAP
    ensure_dir "$GI_ROOT/etc/conf.d"
    {
        printf '# Generated by %s\n' "$GI_NAME"
        printf 'keymap="%s"\n' "$keymap"
        printf 'windowkeys="YES"\n'
    } | write_file_atomic "$GI_ROOT/etc/conf.d/keymaps" 0644
    printf 'KEYMAP=%s\n' "$keymap" | write_file_atomic "$GI_ROOT/etc/vconsole.conf" 0644
    log_info "console keymap set: $keymap"
}

system_write_fstab() {
    local fstab="$GI_ROOT/etc/fstab"
    local root_pass=1
    [[ $CFG_ROOT_FS == btrfs ]] && root_pass=0
    {
        printf '# Generated by %s %s\n' "$GI_NAME" "$GI_VERSION"
        printf '# <device>                                  <mount> <fstype> <options> <dump> <pass>\n'
        printf 'UUID=%-36s /       %-7s defaults        0 %d\n' "$CFG_UUID_ROOT" "$CFG_ROOT_FS" "$root_pass"
        if [[ $CFG_BOOT_MODE == uefi ]]; then
            printf 'UUID=%-36s /efi    vfat    umask=0077      0 2\n' "$CFG_UUID_ESP"
        else
            printf 'UUID=%-36s /boot   %-7s defaults        0 2\n' "$CFG_UUID_BOOT" "$CFG_BOOT_FS"
        fi
        if [[ -n $CFG_UUID_SWAP ]]; then
            printf 'UUID=%-36s none    swap    sw              0 0\n' "$CFG_UUID_SWAP"
        fi
        if [[ -n $CFG_UUID_HOME ]]; then
            printf 'UUID=%-36s /home   %-7s defaults        0 2\n' "$CFG_UUID_HOME" "$CFG_HOME_FS"
        fi
    } | write_file_atomic "$fstab" 0644
    log_info "fstab written"
}

system_root_password() {
    local password
    ui_password_twice "Пароль root" || return 1
    password=$UI_SECRET
    if ! ui_run_input "Установка пароля root" "root:${password}" \
        chroot "$GI_ROOT" /usr/bin/chpasswd; then
        unset password UI_SECRET
        UI_RESULT=""
        return 1
    fi
    unset password UI_SECRET
    UI_RESULT=""
    log_info "root password set"
}

system_create_user() {
    local password groups group group_list=""
    local -a useradd_args=(-m -s /bin/bash)
    [[ $CFG_CREATE_USER == yes ]] || return 0
    for group in users wheel audio video usb cdrom; do
        if [[ -n $(chroot_capture getent group "$group" | head -n 1) ]]; then
            group_list+="${group_list:+,}${group}"
        fi
    done
    [[ -n $group_list ]] && useradd_args+=(-G "$group_list")
    if [[ -z $(chroot_capture id -u "$CFG_USERNAME" | tr -d '[:space:]') ]]; then
        chroot_run "Создание пользователя ${CFG_USERNAME}" \
            useradd "${useradd_args[@]}" "$CFG_USERNAME" || return 1
    else
        log_info "user already exists: $CFG_USERNAME"
        [[ -n $group_list ]] && chroot_run "Добавление ${CFG_USERNAME} в группы" \
            usermod -aG "$group_list" "$CFG_USERNAME" || true
    fi
    ui_password_twice "Пароль пользователя ${CFG_USERNAME}" || return 1
    password=$UI_SECRET
    if ! ui_run_input "Установка пароля ${CFG_USERNAME}" \
        "${CFG_USERNAME}:${password}" chroot "$GI_ROOT" /usr/bin/chpasswd; then
        unset password UI_SECRET
        UI_RESULT=""
        return 1
    fi
    unset password UI_SECRET
    UI_RESULT=""
    groups=$(chroot_capture id -nG "$CFG_USERNAME" | tr -s '[:space:]' ' ')
    log_info "user created: $CFG_USERNAME (groups: ${groups:-none})"
}

step_system() {
    require_mountpoint "$GI_ROOT"
    [[ -f "$GI_ROOT/etc/os-release" ]] || {
        ui_error "Нет базовой системы" "Сначала выполните этапы stage3 и Portage."
        return 1
    }
    chroot_mount || return 1
    system_write_hostname
    system_write_timezone || return 1
    system_write_locale || return 1
    system_write_keymap
    system_write_fstab
    system_root_password || return 1
    system_create_user || return 1
    chroot_run "Финальное обновление окружения" env-update || return 1
    config_save
    log_info "system step finished"
}
